def window_sums(nums, k):
    if k <= 0:
        raise ValueError("k must be positive")
    if k > len(nums):
        return []
    result = []
    window_sum = 0
    for i in range(len(nums)):
        window_sum += nums[i]
        if i >= k:
            window_sum -= nums[i - k]
        if i >= k - 1:
            result.append(window_sum)
    return result
